<template><OperationsFrame title="岗位管理"><el-form inline v-show="showSearch"><el-form-item label="岗位名称"><el-input v-model="keyword" clearable placeholder="名称或编码"/></el-form-item><el-form-item label="状态"><el-select v-model="status" clearable style="width:140px"><el-option label="正常" value="0"/><el-option label="停用" value="1"/></el-select></el-form-item><el-button icon="Search" type="primary" @click="load">搜索</el-button><el-button icon="Refresh" @click="keyword='';status='';load()">重置</el-button></el-form><el-row class="mb8"><el-button type="primary" plain icon="Plus" @click="open()">新增</el-button><right-toolbar v-model:showSearch="showSearch" @queryTable="load"/></el-row><el-table v-loading="loading" :data="filtered"><el-table-column prop="postCode" label="岗位编码" min-width="140" show-overflow-tooltip/><el-table-column prop="postName" label="岗位名称" min-width="150" show-overflow-tooltip/><el-table-column prop="postSort" label="排序" width="80"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='0'?'success':'info'">{{row.status==='0'?'正常':'停用'}}</el-tag></template></el-table-column><el-table-column prop="remark" label="备注" min-width="150" show-overflow-tooltip/><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" icon="Edit" @click="open(row)">修改</el-button><el-button link type="primary" icon="Delete" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="form.postId?'修改岗位':'新增岗位'" width="560px" append-to-body class="access-dialog" :close-on-click-modal="false"><el-form ref="formRef" :model="form" :rules="rules" label-width="100px"><el-form-item label="岗位编码" prop="postCode"><el-input v-model="form.postCode" maxlength="64"/></el-form-item><el-form-item label="岗位名称" prop="postName"><el-input v-model="form.postName" maxlength="50"/></el-form-item><el-form-item label="显示排序" prop="orderNum"><el-input-number v-model="form.postSort" :min="0" :max="9999"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="0">正常</el-radio><el-radio value="1">停用</el-radio></el-radio-group></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="saving" @click="save">确 定</el-button><el-button @click="visible=false">取 消</el-button></template></el-dialog></OperationsFrame></template>
<script setup>
import {ref,reactive,computed,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import OperationsFrame from '@/views/operations/OperationsFrame.vue'
import {posts,savePost,deletePost} from '@/api/organization'
const rows=ref([]),loading=ref(false),saving=ref(false),visible=ref(false),showSearch=ref(true),keyword=ref(''),status=ref(''),form=reactive({}),formRef=ref()
const filtered=computed(()=>rows.value.filter(r=>(!keyword.value||`${r.postName} ${r.postCode}`.includes(keyword.value))&&(!status.value||r.status===status.value)))
const rules={postName:[{required:true,message:'请输入岗位名称',trigger:'blur'}],postCode:[{required:true,pattern:/^[A-Za-z][A-Za-z0-9_-]{1,63}$/,message:'2～64位字母、数字、下划线或短横线，以字母开头',trigger:'blur'}]}
async function load(){loading.value=true;try{rows.value=(await posts()).data}finally{loading.value=false}}
function open(row){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{postCode:'',postName:'',postSort:0,status:'0',remark:''},row||{});visible.value=true}
async function save(){if(!await formRef.value.validate().catch(()=>false))return;saving.value=true;try{await savePost(form);visible.value=false;ElMessage.success('岗位已保存');await load()}catch(e){console.error(e)}finally{saving.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`确认删除岗位“${row.postName}”？`,'提示',{type:'warning'});await deletePost(row.postId);ElMessage.success('岗位已删除');await load()}catch(e){if(e!=='cancel'&&e!=='close')console.error(e)}}
onMounted(load)
</script>
